def rle_encode(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 1
    prev_char = s[0]
    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            result.append(f"{prev_char}{count}")
            prev_char = char
            count = 1
    result.append(f"{prev_char}{count}")
    return "".join(result)
