def flatten(nested: list) -> list:
    """Flatten arbitrarily nested lists into one list, preserving order."""
    result = []
    def recurse(lst):
        for item in lst:
            if isinstance(item, list):
                recurse(item)
            else:
                result.append(item)
    recurse(nested)
    return result
