def count_params(shapes: list[tuple[int, ...]]) -> int:
    """Total number of elements across tensors with the given shapes (a 0-dim shape () has 1 element)."""
    total = 0
    for shape in shapes:
        if not shape:
            total += 1
        else:
            total += sum(shape)
    return total
