def lru_misses(capacity: int, accesses: list[int]) -> int:
    from collections import deque

    cache = deque()
    misses = 0

    for access in accesses:
        if len(cache) < capacity:
            cache.append(access)
        else:
            # Check if the access is in the cache
            found = False
            for i in range(len(cache)):
                if cache[i] == access:
                    cache[i] = access  # Update the cache
                    found = True
                    break
            if not found:
                misses += 1
                cache.append(access)

    return misses
```

