def parse_duration(s: str) -> int:
    """Seconds in a duration like "1h30m15s" (each of h, m, s optional, in that order); raise ValueError if invalid or empty."""
    if not s:
        raise ValueError("Duration must not be empty")

    total_seconds = 0
    i = 0

    while i < len(s):
        if s[i] in 'hms':
            # Extract the number part
            num = 0
            while i < len(s) and s[i].isdigit():
                num = num * 10 + int(s[i])
                i += 1
            if i >= len(s):
                raise ValueError("Invalid duration")

            # Convert to seconds
            if s[i] == 'h':
                total_seconds += num * 3600
                i += 1
            elif s[i] == 'm':
                total_seconds += num * 60
                i += 1
            elif s[i] == 's':
                total_seconds += num
                i += 1
            else:
                raise ValueError("Invalid unit")
        else:
            # Skip non-unit characters
            i += 1

    return total_seconds
